			if (!options.root) {
				this._oncreate = [];
				${(compiler.hasComponents || target.hasComplexBindings) && `this._beforecreate = [];`}
				${(compiler.hasComponents || target.hasIntroTransitions) && `this._aftercreate = [];`}
