global.requestAnimationFrame = () => {};
window.calls = [];
let resolve;
const promise = new Promise(r => { resolve = r; });
const source = `<script>export default { transitions: { fade(node) { window.calls.push(node.textContent); return { duration: 100 }; } } }</script>{#await promise}<p transition:fade>loading...</p>{:then value}<p transition:fade>{value}</p>{/await}`;
const { js } = compiler.compile(source, { format: 'cjs', name: 'AwaitTransition', shared: path.resolve('shared.js') });
const module = { exports: {} };
new Function('require', 'module', 'exports', js.code)(require, module, module.exports);
const Component = module.exports;
const component = new Component({ target: document.querySelector('main'), data: { promise } });
if (window.calls.length !== 1) throw new Error(`expected pending intro, saw ${window.calls.length}`);
resolve('resolved');
Promise.resolve().then(() => Promise.resolve()).then(() => {
  if (window.calls.length !== 2) throw new Error(`expected resolved intro, saw ${window.calls.length}`);
  if (!document.querySelector('main').textContent.includes('resolved')) throw new Error('resolved branch not mounted');
  if (!document.querySelector('main').textContent.includes('loading...')) throw new Error('outro branch detached before transition completed');
  component.destroy();
  console.log('await transitions: initial intro, branch intro, and outro retention verified');
}).catch(error => { console.error(error); process.exitCode = 1; });
